{
  "summary": "Renewal request from Acme Cloud Services with a 12% price increase needs verification against current contract terms, SLA performance, and any owed credits before drafting a response.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (pricing, terms, renewal/notice clauses, currency), read any SLA or performance policy documents, use the SLA credit calculator to determine any SLA misses and credits owed for the current contract period, and if amounts are in a foreign currency use the currency converter to express them in our reporting currency.",
      "why": "The executor needs the full facts—current price, contract terms, SLA performance, and any credits owed—to evaluate the proposed 12% increase and draft an accurate response."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft a reply to Acme Cloud Services addressing the renewal request, referencing current contract terms, any SLA credits owed, and a recommended counter-position on the proposed 12% price increase, for human review and approval.",
      "why": "The executor synthesizes the gathered facts into the final vendor-facing response."
    }
  ],
  "escalate": null
}
